import {ITEMS,ROLES,ROUTES,LAUNCHERS,SOURCES} from './data.js';
import * as E from './engine.js';
import {ChipAudio} from './audio.js';
const root=document.querySelector('#root'),modal=document.querySelector('#modal'),body=document.querySelector('#modal-body'),audio=new ChipAudio();
let game=null,saved=null,menu=null,home=true;try{saved=JSON.parse(localStorage.getItem('beeyond-v6')||localStorage.getItem('beeyond-v5'));if(!E.validSave(saved))saved=null;}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(text,action,cls='',disabled=false)=>`<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
const bee=(mood='sleep')=>`<span class="bee ${mood}" role="img" aria-label="Abejorro ${mood==='sleep'?'en reposo':mood==='risk'?'en alerta':'animado'}"></span>`;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3300);}
function save(){saved=structuredClone(game);try{localStorage.setItem('beeyond-v6',JSON.stringify(game));}catch{toast('No se pudo guardar. Mantén esta pestaña abierta.');}}
function update(s){game=s;save();render();if(menu)drawMenu();}
function objective(){if(!game.parts.some(x=>x.startsWith('chamber')))return ['Conoce a tus pequeñas pasajeras','Abre Biología y elige una cámara para protegerlas.'];if(!game.grants.includes(0))return ['Comprueba tu primer diseño','En Dirección, revisa cámara, potencia y masa para obtener 150 créditos.'];if(!game.grants.includes(1))return ['Compara dos caminos hacia Marte','En Dirección, examina ambas rutas y solicita 200 créditos.'];if(E.errors(game).length)return ['Ajusta tu nave','Revisa en Dirección lo que falta antes del despegue.'];return ['Todo listo para una gran aventura','Puedes mejorar tus instrumentos o despegar desde Dirección.'];}
function hud(){const t=E.stats(game);return `<header class="hud"><div class="brand">BEEYOND MARS <small> / AURELIA</small></div><div class="metrics"><span>Fondos <strong>${t.budget}</strong></span><span>Masa <strong>${t.kg}/${E.launcher(game).cap} kg</strong></span><span>Consumo <strong>${t.use}/${t.power} W</strong></span></div><div class="hud-tools">${b('♪ Audio','audio')}${b('⛶ Pantalla','fullscreen')}${b('☰ Menú','pause')}</div></header>`;}
function render(){if(home){root.innerHTML=`<section class="title"><div class="title-card"><span class="eyebrow">UNA PEQUEÑA VIDA · UN GRAN VIAJE</span>${bee('')}<h1>BEEYOND MARS</h1><p>Explora el laboratorio, diseña una nave y cuida a tus abejas en una misión educativa hacia Marte.</p><div class="actions">${b('Nueva misión','new','primary')}${saved?b('Continuar','continue'):''}</div><div class="actions">${b('♪ Música y sonido','audio')}${b('⛶ Pantalla completa','fullscreen')}</div><small>RPG educativo · guardado automático · música original de 8 bits</small></div></section>`;return;}
root.innerHTML=`<section class="game">${hud()}<div class="world">${game.phase==='lab'||game.phase==='launch'?lab():game.phase==='voyage'?flight():result()}</div><footer class="dock">${game.phase==='lab'||game.phase==='launch'?`<div class="actions">${ROLES.map((r,i)=>b(['Biología','Ingeniería','Comunicaciones','Dirección'][i],`station:${[1,0,2,3][i]}`)).join('')}</div><span class="hint">WASD / flechas: caminar · E: interactuar<br>También puedes pulsar una estación directamente.</span>`:`<span class="hint">Cada decisión cambia el resultado de esta simulación.</span><div class="actions">${b('Bitácora','journal')}${b('Qué significan los datos','learn')}</div>`}</footer></section>`;}
function lab(){const q=objective();return `<canvas id="world" width="640" height="352" aria-label="Laboratorio Aurelia. Usa WASD o flechas para caminar, E para interactuar; también hay botones accesibles de cada estación."></canvas><div class="quest"><span class="eyebrow">TU SIGUIENTE PASO</span><b>${q[0]}</b><small>${q[1]}</small></div><div class="bee-monitor">${bee()}<small>ABEJAS EN REPOSO<br>Carga biológica experimental</small></div><div class="dpad"><button data-move="ArrowUp" aria-label="Arriba">↑</button><button data-move="ArrowLeft" aria-label="Izquierda">←</button><button data-move="ArrowDown" aria-label="Abajo">↓</button><button data-move="ArrowRight" aria-label="Derecha">→</button></div>`;}
function flight(){const f=game.flight;return `<div class="flight"><div><span class="eyebrow">TRÁNSITO A MARTE</span><h2>Día ${game.day} de ${E.route(game).days}</h2><div class="progress"><i style="width:${game.day/E.route(game).days*100}%"></i></div></div><div class="chamber">${bee(f.risk>35?'risk':'sleep')}<b>${f.risk>35?'Necesitan atención':'Reposo de la carga'}</b><div class="statusline">${f.temp.toFixed(1)} °C · ${f.humidity.toFixed(0)}% HR</div></div><div><div class="metrics"><span>Riesgo <strong>${Math.round(f.risk)}/100</strong></span><span>Batería <strong>${Math.round(f.charge)} Wh</strong></span><span>Datos recibidos <strong>${Math.round(f.sent)} MB</strong></span><span>Señal <strong>${Math.round(E.delay(game))} min</strong></span></div><div class="flight-bottom"><div><b>${f.pending?'La nave necesita una decisión':'Observa, aprende y sigue avanzando'}</b><p>${f.pending?'El tiempo está detenido hasta que elijas una respuesta.':'Cada etapa simula hasta 30 días. Revisa cómo cambian la energía, el ambiente y los datos.'}</p></div>${b(f.pending?'Resolver incidente':`Avanzar ${Math.min(30,E.route(game).days-game.day)} días`,f.pending?'event':'advance','primary')}</div></div></div>`;}
function result(){const r=E.report(game),f=game.flight;const title={success:'¡Marte a la vista!',partial:'Llegamos, con aprendizajes',failure:'Hora de rediseñar'};return `<div class="result"><span class="eyebrow">INFORME DE MISIÓN / INTENTO ${game.attempt}</span>${bee(r.kind==='success'?'happy':r.kind==='partial'?'':'risk')}<h2>${title[r.kind]}</h2><p>${r.reason==='power'?'La nave se quedó sin energía en dos etapas seguidas. Reduce el consumo o aumenta la generación.':r.reason==='climate'?'El ambiente aumentó el riesgo de la carga. Compara refrigeración activa, sensores y una respuesta autónoma ante emergencias.':r.reason==='data'?'La nave llegó, pero faltaron observaciones. Compara capacidad de transmisión, memoria y compresión.':'Tu diseño equilibró energía, ambiente y comunicación. La autonomía permitió responder lejos de la Tierra.'}</p><div class="metrics"><span>${game.day} días</span><span>Riesgo ${Math.round(f.risk)}/100</span><span>${Math.round(f.sent)} MB recibidos</span><span>${Math.round(f.lost)} MB perdidos</span><span>${r.score} puntos</span></div><p>¿Qué cambiarías y por qué? Puedes volver al laboratorio conservando tus equipos y fondos obtenidos.</p><div class="actions">${b('Rediseñar y reintentar','redesign','primary')}${b('Revisar bitácora','journal')}${b('Descargar informe','download')}</div><small>Resultado de un modelo educativo hipotético; no demuestra supervivencia real en el espacio.</small></div>`;}
function open(which){keys.clear();menu=which;drawMenu();if(!modal.open)modal.showModal();}
function close(){modal.close();menu=null;keys.clear();}
function drawMenu(){let html='';if(menu==='new'){html=`<h2>Tu misión comienza aquí</h2><p>Dispones de 900 créditos para transportar abejas en reposo. Equilibra energía, masa y comunicación; las mejoras se desbloquean al revisar tu diseño.</p><label>Personas en este dispositivo <select id="players"><option value="1">1 · todos los roles</option><option value="2">2 · turnos locales</option><option value="3">3 · turnos locales</option><option value="4">4 · turnos locales</option></select></label><p>${saved?'Al aceptar, se reemplazará la partida guardada.':'Puedes caminar o acceder directamente a cada estación.'}</p>${b('Aceptar misión','accept','primary')}`;}
else if(menu==='audio'){html=`<h2>Música y soniditos</h2><p>Melodía chiptune original con ondas cuadradas, arpegios y bajo triangular.</p><label>Música <input aria-label="Volumen de música" type="range" min="0" max="0.6" step="0.01" data-volume="music" value="${audio.music}"></label><label>Efectos <input aria-label="Volumen de efectos" type="range" min="0" max="0.8" step="0.01" data-volume="sfx" value="${audio.sfx}"></label>${b('Probar sonido','test-sound')}${b('Silenciar todo','mute')}<p><small>Los ajustes se guardan. El audio se pausa al cambiar de pestaña. Cero en un control lo silencia.</small></p>`;}
else if(menu==='pause'){html=`<h2>Misión en pausa</h2><p>La partida se guarda automáticamente en este navegador.</p><div class="actions">${b('Audio','audio')}${b('Bitácora','journal')}${b('Guía y fuentes','learn')}${b('Volver al título','home')}</div>`;}
else if(menu==='journal'){html=`<h2>Bitácora</h2><div class="log">${game?.log.length?game.log.map(l=>`<p><b>Día ${l.day}</b> · ${esc(l.es)}</p>`).join(''):'Tus decisiones y resultados aparecerán aquí.'}</div>`;}
else if(menu==='learn'){html=`<h2>Pequeña guía de misión</h2><div class="cards">${[['Potencia · W','Lo que la nave produce y consume en cada instante. Al llegar, los paneles producen menos.'],['Energía · Wh','La reserva de la batería. Se agota si el consumo supera la generación durante mucho tiempo.'],['Datos · MB','Observaciones científicas recibidas en la Tierra. Una antena mejor envía más datos, pero no elimina el retraso de la señal.'],['Riesgo · 0–100','Índice del juego por condiciones ambientales. No es una probabilidad real de supervivencia.']].map(([a,c])=>`<article class="card"><h3>${a}</h3><p>${c}</p></article>`).join('')}</div><p class="notice">Modelo educativo hipotético. Equipos, créditos, riesgos y rutas exactas son parámetros del equipo. El MVP termina al llegar; no simula aterrizaje ni polinización.</p><h3>Fuentes y créditos</h3>${SOURCES.filter(s=>s.url).map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title}</a></p>`).join('')}<p><small>Concepto: equipo BeeYond Mars. Arte original asistido por IA y recursos del proyecto. Música procedural original. Inspiración retro; sin música ni personajes de otros juegos.</small></p>`;}
else if(menu==='event'){const thermal=game.flight.pending==='thermal';html=`<h2>${thermal?'Alerta de refrigeración':'Enlace de datos inestable'}</h2><p>${thermal?'La temperatura puede subir. La señal tarda en ir y volver: ¿puede decidir la nave por sí misma?':'No todo puede transmitirse a la vez. Decide qué observaciones conservar y cómo enviarlas.'}</p><div class="cards">${E.options(game).map(o=>`<article class="card"><h3>${o.name[1]}</h3><p>${o.desc[1]}</p>${b('Elegir respuesta',`resolve:${o.id}`,'primary',o.disabled)}</article>`).join('')}</div>`;}
else if(menu.startsWith('station:')){const role=Number(menu.split(':')[1]);html=`<span class="eyebrow">ESTACIÓN ${ROLES[role][1].toUpperCase()}</span><h2>${['Construye tu nave','Cuida a tus abejas','Escucha desde la Tierra','Prepara el despegue'][role]}</h2>`;if(role!==3){html+=`<p>${['La nave necesita generar más potencia de la que consume, también al llegar.','Tus pasajeras viajan en reposo. Una cámara activa controla mejor el ambiente, pero consume más energía.','Recibir observaciones permite aprender de la misión. Más instrumentos también consumen energía.'][role]}</p><div class="cards">${ITEMS.filter(i=>i.role===role).map(i=>`<article class="card ${game.parts.includes(i.id)?'selected':''}"><img src="assets/sprites/equipment/${i.icon}.png" alt=""><h3>${i.name[1]}</h3><p>${i.desc[1]}</p><small>${i.cost} créditos · ${i.kg} kg · ${i.gen?'+'+i.gen:i.w} W</small>${b(game.parts.includes(i.id)?'Retirar equipo':'Instalar',`item:${i.id}`,game.parts.includes(i.id)?'':'primary')}</article>`).join('')}</div><p class="statusline">Fondos disponibles: ${E.stats(game).budget} créditos. Los equipos se pueden retirar sin penalización.</p>`;}
else{const errors=E.errors(game),t=E.stats(game);html+=`<div class="actions">${b(game.grants.includes(0)?'✓ Revisión inicial':'+150 · Revisar diseño','grant:0','',game.grants.includes(0))}${b(game.grants.includes(1)?'✓ Rutas comparadas':'+200 · Completar comparación','grant:1','',game.grants.includes(1))}</div><p class="statusline">Primero instala una cámara con suficiente potencia. Después selecciona ambas rutas para compararlas.</p><div class="cards">${ROUTES.map(r=>`<article class="card ${game.route===r.id?'selected':''}"><h3>${r.name[1]}</h3><p>${r.days} días · Δv ${r.dv} km/s</p><small>${r.id==='fast'?'Menor tiempo, mayor exigencia de maniobra.':'Mayor tiempo, menor exigencia de maniobra.'}</small>${b(`${game.compared.includes(r.id)?'✓ ':''}Examinar y elegir`, `route:${r.id}`)}</article>`).join('')}</div><label>Lanzador <select id="launcher">${LAUNCHERS.map(l=>`<option value="${l.id}" ${game.launcher===l.id?'selected':''}>${l.name} · ${l.cap} kg · ${l.cost} créditos</option>`).join('')}</select></label><div class="notice ${errors.length?'bad':''}">${errors.length?errors.map(e=>esc(e[1])).join('<br>'):'✓ Cámara, masa, potencia de salida, trayectoria y fondos compatibles.'}<br>Potencia al llegar: ${Math.round(t.arrivalPower)} W · consumo ${t.use} W.${t.arrivalPower<t.use?'<br>Atención: la batería deberá cubrir el déficit al llegar.':''}</div>${b('Despegar hacia Marte','launch','primary',E.milestone(game)<4)} <small>Requiere ambas revisiones y un diseño compatible.</small>`;}}
body.innerHTML=html;}
async function action(a){const [key,id]=a.split(':');if(key!=='fullscreen'){try{await audio.start();}catch{toast('El navegador no pudo activar el audio.');}}audio.effect();if(key==='close')return close();if(key==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Pantalla completa no disponible. El juego ya ocupa la ventana.');}return;}if(['audio','pause','new','journal','learn','event'].includes(key))return open(key);if(key==='test-sound'){audio.effect('success');return;}if(key==='mute'){audio.set('music',0);audio.set('sfx',0);return drawMenu();}if(key==='accept'){game=E.fresh(Number(document.querySelector('#players').value));home=false;close();save();render();return;}if(key==='continue'){game=structuredClone(saved);if(game.phase==='launch')game.phase='lab';home=false;render();return;}if(key==='home'){close();home=true;render();return;}if(key==='station'){game.role=Number(id);save();return open(a);}if(key==='item'){const next=E.toggle(game,id);if(next===game){toast('No alcanzan los fondos. Retira otro equipo o completa una revisión.');audio.effect('error');}else audio.effect('equip');update(next);return;}if(key==='grant'){const next=E.claim(game,Number(id));if(next.grants.length===game.grants.length)toast(id==='0'?'Instala una cámara y comprueba que tenga suficiente potencia y capacidad de carga.':'Completa la primera revisión y selecciona ambas rutas.');else{toast('¡Fondos de investigación recibidos!');audio.effect('success');}update(next);return;}if(key==='route'){update(E.selectRoute(game,id));return;}if(key==='launch'){const next=E.launch({...game,phase:'launch'});if(next.phase==='voyage'){close();update(next);audio.effect('success');}return;}if(key==='advance'){update(E.advance(game));audio.effect('advance');if(game.flight.pending)open('event');return;}if(key==='resolve'){const next=E.resolve(game,id);close();update(next);toast('Decisión registrada. Revisa el ambiente y continúa.');return;}if(key==='redesign'){update(E.redesign(game));return;}if(key==='download'){const blob=new Blob([JSON.stringify({report:E.report(game),mission:game},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BeeYondMars-informe.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target)action(target.dataset.action);});document.addEventListener('input',e=>{if(e.target.dataset.volume)audio.set(e.target.dataset.volume,e.target.value);});document.addEventListener('change',e=>{if(e.target.id==='launcher'){const next=E.chooseLauncher(game,e.target.value);if(next===game)toast('No hay fondos suficientes para este lanzador.');update(next);}});modal.addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('visibilitychange',()=>{keys.clear();document.hidden?audio.pause():audio.resume();});window.addEventListener('blur',()=>keys.clear());
const bg=new Image(),crew=new Image();bg.src='assets/backgrounds/lab_aurelia_8bit.png';crew.src='assets/neutral-crew.png';let pos={x:310,y:180},direction=0,last=0,frame=0;const keys=new Set(),stations=[{x:130,y:294,role:0},{x:145,y:145,role:1},{x:512,y:145,role:2},{x:510,y:293,role:3}];
function interact(){const s=stations.reduce((a,b)=>Math.hypot(a.x-pos.x,a.y-pos.y)<Math.hypot(b.x-pos.x,b.y-pos.y)?a:b);if(Math.hypot(s.x-pos.x,s.y-pos.y)<110)action('station:'+s.role);else toast('Acércate a una estación o usa los botones inferiores.');}
document.addEventListener('keydown',e=>{if(home||modal.open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());}if(!e.repeat&&['e','E','Enter',' '].includes(e.key)){e.preventDefault();if(game.phase==='lab')interact();}if(e.key==='Escape')open('pause');});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));document.addEventListener('pointerdown',e=>{if(e.target.dataset.move){e.preventDefault();e.target.setPointerCapture(e.pointerId);keys.add(e.target.dataset.move.toLowerCase());}});document.addEventListener('pointerup',()=>keys.clear());document.addEventListener('pointercancel',()=>keys.clear());
root.addEventListener('click',e=>{if(e.target.id!=='world')return;const r=e.target.getBoundingClientRect(),scale=Math.min(r.width/640,r.height/352),x=(e.clientX-r.left-(r.width-640*scale)/2)/scale,y=(e.clientY-r.top-(r.height-352*scale)/2)/scale;const s=stations.find(s=>Math.hypot(x-s.x,y-s.y)<62);if(s)action('station:'+s.role);});
function draw(now){const dt=Math.min((now-last)/1000,.04);last=now;const canvas=document.querySelector('#world');if(canvas){let dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);if(!modal.open&&(dx||dy)){const length=Math.hypot(dx,dy);const nx=Math.max(32,Math.min(608,pos.x+dx/length*115*dt)),ny=Math.max(128,Math.min(318,pos.y+dy/length*115*dt));const blocked=(x,y)=>((x>48&&x<208&&y>208&&y<280)||(x>416&&x<592&&y>208&&y<280)||(x>300&&x<344&&y>244&&y<284));if(!blocked(nx,pos.y))pos.x=nx;if(!blocked(pos.x,ny))pos.y=ny;direction=dx<0?1:dx>0?2:dy<0?3:0;frame=Math.floor(now/140)%4;}else frame=0;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,640,352);if(bg.complete&&bg.naturalWidth)c.drawImage(bg,0,0,640,352);const sprite=(x,y,dir,f)=>{if(crew.complete&&crew.naturalWidth)c.drawImage(crew,f*crew.width/4,dir*crew.height/4,crew.width/4,crew.height/4,Math.round(x-24),Math.round(y-42),48,48);};stations.forEach(s=>{sprite(s.x+40,s.y,0,0);const near=Math.hypot(s.x-pos.x,s.y-pos.y)<110;c.fillStyle=near?'#ffe090':'#dbe9d4';c.fillRect(s.x-4,s.y-16,8,8);c.fillStyle='#142237';c.fillRect(s.x-35,s.y+12,70,17);c.fillStyle='#f4e7ba';c.font='11px monospace';c.textAlign='center';c.fillText(['TALLER','BIOLOGÍA','ENLACE','DIRECCIÓN'][s.role],s.x,s.y+24);});sprite(pos.x,pos.y,direction,frame);c.fillStyle='#ffe096';c.fillRect(Math.round(pos.x-3),Math.round(pos.y-47),6,3);}requestAnimationFrame(draw);}render();requestAnimationFrame(draw);
